<template><div class="page-container"><el-table :data="tableData" border stripe v-loading="loading"><el-table-column prop="orderNo" label="工单编号" width="160"/><el-table-column prop="productId" label="产品ID"/><el-table-column prop="quantity" label="计划数量"/><el-table-column prop="producedQty" label="已完成"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="['info','primary','success'][row.status]" size="small">{{['待生产','生产中','已完成'][row.status]}}</el-tag></template></el-table-column><el-table-column label="操作" width="160"><template #default="{row}"><el-button v-if="row.status===0" link type="primary" @click="start(row)">开始</el-button><el-button v-if="row.status===1" link type="success" @click="finish(row)">完成</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" layout="total,prev,pager,next" @current-change="fetchData" style="margin-top:16px"/></div></template>
<script setup>import {ref,onMounted}from 'vue';import {listProdOrders,startProdOrder,completeProdOrder}from '@/api/production';import {ElMessage}from 'element-plus';const loading=ref(false);const tableData=ref([]);const total=ref(0);const page=ref(1);onMounted(()=>fetchData());async function fetchData(){loading.value=true;try{const res=await listProdOrders({page:page.value});tableData.value=res.data.records;total.value=res.data.total}finally{loading.value=false}}async function start(row){await startProdOrder(row.orderId);ElMessage.success('已开始');fetchData()}async function finish(row){await completeProdOrder(row.orderId);ElMessage.success('已完成');fetchData()}</script>
